from pathlib import Path
s=Path('Test/Tam/bank97-integrate.cs.txt').read_text();h=s[s.index('static GameObject Find'):s.index('public void Execute')]
body=r'''public void Execute(ExecutionResult result){var f=Find("R20_Whole_Source_Export/Surface_104").GetComponent<MeshFilter>();var m=Readable(f.sharedMesh);var vs=m.vertices.Select(p=>f.transform.TransformPoint(p)).ToArray();var ts=m.triangles;string log=AssetDatabase.GetAssetPath(f.sharedMesh)+"\n";foreach(var p in new[]{new Vector3(664.211f,1.8746f,420.4985f),new Vector3(667.41370f,1.67724f,425.15030f)}){float best=100;string desc="";for(int i=0;i<ts.Length;i+=3){var a=vs[ts[i]];var b=vs[ts[i+1]];var c=vs[ts[i+2]];var n=Vector3.Cross(b-a,c-a);if(n.sqrMagnitude<1e-16)continue;var q=p-n*Vector3.Dot(p-a,n)/n.sqrMagnitude;float d00=Vector3.Dot(b-a,b-a),d01=Vector3.Dot(b-a,c-a),d11=Vector3.Dot(c-a,c-a),d20=Vector3.Dot(q-a,b-a),d21=Vector3.Dot(q-a,c-a);float den=d00*d11-d01*d01;if(Mathf.Abs(den)<1e-16)continue;float v=(d11*d20-d01*d21)/den,w=(d00*d21-d01*d20)/den;if(v>=-.0001f&&w>=-.0001f&&v+w<=1.0001f){float d=Vector3.Distance(q,p);if(d<best){best=d;desc="tri="+i/3+" q="+q.ToString("F7")+" bary="+new Vector3(1-v-w,v,w).ToString("F6")+" a="+a.ToString("F5")+" b="+b.ToString("F5")+" c="+c.ToString("F5");}}}log+="p="+p.ToString("F7")+" plane distance="+best+" "+desc+"\n";}File.WriteAllText("Test/KetQua/journey_v48/bank_r97/projection-debug.txt",log);result.Log(log);}}'''
Path('Test/Tam/bank97-projection-debug.cs.txt').write_text('using UnityEngine;using Unity.Collections;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using System.IO;using System.Linq;using System.Collections.Generic;\ninternal class CommandScript:IRunCommand{'+h+body)
